/**
 * tcRunRegistry.js — gh-1329 per-TC run bookkeeping.
 *
 * Infra prerequisite ("Per-TC run bookkeeping … written where automation
 * results are already processed"): every TC that passes a run is recorded
 * with its **lastGreenSha** and **environment fingerprint** — that green is
 * what turns a fresh TC into a *validated guard* (a fresh TC cannot bounce
 * the bug by construction) and what later makes guard-failure attribution a
 * measurement: the triage engine (tcTriage.js) compares the failing run's
 * SHA + env fingerprint against this record and only a build change can
 * escalate to a differential rerun / earned bounce.
 *
 *   Greens     validated=true + lastGreenSha + lastGreenEnvFingerprint +
 *              lastGreenAt; a new green refreshes the fingerprint and
 *              RESETS the consecutive-red streak (a green between reds
 *              means the fix worked — the loop counter is a streak, not a
 *              lifetime total; "no new counter" — this is the run
 *              bookkeeping the design already calls for).
 *
 *   Reds       redRounds++ per red run for the TC (independent per TC),
 *              with lastRedAt + lastVerdict — the bounce-cap input for
 *              tcTriage (repeated attributed failures hit maxReworkRounds →
 *              escalation, never an infinite loop).
 *
 *   Storage    one machine-parseable marker comment per update on the bug
 *              ticket — the house `dmtools:` marker pattern (same family as
 *              the gh-1332 finding registry). The newest machine-authored
 *              marker wins. FAILS CLOSED: no configured machine identity →
 *              nothing is trusted.
 *
 * Pure module — no dmtools globals; callers fetch comments and post the
 * built marker. GraalJS-clean (var + plain functions, JSON-safe data).
 */
'use strict';

var reviewVerdicts = require('./reviewVerdicts.js');

var MARKER_PREFIX = '<!-- dmtools:tc-run-registry ';
var MARKER_SUFFIX = ' -->';
var REGISTRY_VERSION = 1;

// ── shape ────────────────────────────────────────────────────────────────────

function emptyRegistry() {
    return { v: REGISTRY_VERSION, at: new Date().toISOString(), tcs: {} };
}

function deepCopyRegistry(r) {
    return JSON.parse(JSON.stringify(r || emptyRegistry()));
}

function entryOf(r, tcKey) {
    return (r && r.tcs && r.tcs[tcKey]) ? r.tcs[tcKey] : null;
}

/** The bookkeeping record for one TC, or null when it has none. */
function stateOf(r, tcKey) {
    return entryOf(r, tcKey);
}

function isKnown(r, tcKey) {
    return !!entryOf(r, tcKey);
}

/**
 * A TC's validation state for triage: true once the TC has passed at least
 * one run (a validated guard / validated own oracle). Fresh TCs are not
 * validated — their first run is validation.
 */
function isValidated(r, tcKey) {
    var e = entryOf(r, tcKey);
    return !!(e && e.validated === true);
}

/** The consecutive-red streak for a TC (0 when none). */
function redRoundsOf(r, tcKey) {
    var e = entryOf(r, tcKey);
    return (e && e.redRounds) || 0;
}

// Entry fields a new state carries over from the previous one.
var CARRIED_ENTRY_FIELDS = ['role', 'lastGreenSha', 'lastGreenEnvFingerprint', 'lastGreenAt', 'lastRedAt', 'lastVerdict'];

/** The carried-over entry state (prev counters kept, stamps cleared per route). */
function carriedEntryState(prevEntry) {
    var prev = prevEntry || {};
    var state = {
        validated: prev.validated === true,
        greens: prev.greens || 0,
        redRounds: prev.redRounds || 0
    };
    CARRIED_ENTRY_FIELDS.forEach(function(k) {
        state[k] = prev[k] || null;
    });
    return state;
}

// The evidence fields a green run overrides on the carried state.
var GREEN_OVERRIDE_FIELDS = [['role', 'role'], ['lastGreenSha', 'sha'], ['lastGreenEnvFingerprint', 'envFingerprint']];

function applyGreenEvidence(state, evidence, at) {
    GREEN_OVERRIDE_FIELDS.forEach(function(pair) {
        state[pair[0]] = evidence[pair[1]] || state[pair[0]];
    });
    state.validated = true;
    state.lastGreenAt = at;
    state.greens = state.greens + 1;
    state.redRounds = 0;
}

/**
 * Records a green run for a TC: validates it, stores lastGreenSha + env
 * fingerprint, resets the red streak. Returns the NEW registry (never
 * mutates the input).
 */
function recordGreen(prev, tcKey, evidence) {
    var at = (evidence && evidence.at) || new Date().toISOString();
    var r = deepCopyRegistry(prev);
    r.at = at;
    var state = carriedEntryState(entryOf(r, tcKey));
    applyGreenEvidence(state, evidence || {}, at);
    r.tcs[tcKey] = state;
    return r;
}

/**
 * Records a red run for a TC: advances the consecutive-red streak.
 * Returns the NEW registry (never mutates the input).
 */
function recordFailure(prev, tcKey, info) {
    var at = (info && info.at) || new Date().toISOString();
    var r = deepCopyRegistry(prev);
    r.at = at;
    var state = carriedEntryState(entryOf(r, tcKey));
    state.role = (info && info.role) || state.role;
    state.lastRedAt = at;
    state.redRounds = state.redRounds + 1;
    state.lastVerdict = (info && info.verdict) || null;
    r.tcs[tcKey] = state;
    return r;
}

// ── marker persistence (the house dmtools: marker pattern) ───────────────────

// Marker hygiene (escaping) and the parse walk live in reviewVerdicts — the
// shared dmtools: marker plumbing (gh-1329 rework, gh-1251 duplication
// ratchet): this module keeps only its MARKER_PREFIX and payload adapter.

function registryPayload(r) {
    return {
        v: r.v || REGISTRY_VERSION,
        at: r.at || new Date().toISOString(),
        tcs: r.tcs || {}
    };
}

function validatedCount(r) {
    var n = 0;
    var tcs = (r && r.tcs) || {};
    for (var k in tcs) {
        if (tcs.hasOwnProperty(k) && tcs[k] && tcs[k].validated === true) n++;
    }
    return n;
}

function registryNote(r) {
    return '\uD83D\uDCD8 TC run registry (gh-1329) — ' + validatedCount(r) +
        ' validated TC record(s). Machine-managed last-green bookkeeping; please do not edit or reply.';
}

/**
 * Builds the registry marker comment for an update. Returns null for a
 * non-postable registry (no tcs map — a registry without tcs is not a
 * registry).
 */
function buildRegistryMarker(r) {
    if (!r || !r.tcs || typeof r.tcs !== 'object') return null;
    return MARKER_PREFIX + JSON.stringify(registryPayload(r), reviewVerdicts.markerSafeReplacer) + MARKER_SUFFIX + '\n' + registryNote(r);
}

function registryFromPayload(parsed) {
    if (!parsed || !parsed.tcs || typeof parsed.tcs !== 'object') return null;
    return {
        v: parseInt(parsed.v, 10) || REGISTRY_VERSION,
        at: String(parsed.at || ''),
        tcs: parsed.tcs
    };
}

/**
 * Parses ALL registry records from a ticket comments payload. FAILS CLOSED:
 * no configured machine-identity allowlist trusts nothing (the
 * machineAuthor doctrine — the registry gates bug verdicts).
 * Returns records oldest-first.
 */
function parseRegistryComments(comments, opts) {
    return reviewVerdicts.parseMarkerComments(comments, opts, MARKER_PREFIX, MARKER_SUFFIX,
        function(parsed) {
            var r = registryFromPayload(parsed);
            return r ? { registry: r, at: r.at } : null;
        }, true);
}

/**
 * The newest trusted registry record for a ticket, or null when none exists.
 */
function latestRegistry(comments, opts) {
    var records = parseRegistryComments(comments, opts);
    return records.length ? records[records.length - 1] : null;
}

if (typeof module !== 'undefined' && module.exports) {
    module.exports = {
        MARKER_PREFIX: MARKER_PREFIX,
        MARKER_SUFFIX: MARKER_SUFFIX,
        REGISTRY_VERSION: REGISTRY_VERSION,
        emptyRegistry: emptyRegistry,
        stateOf: stateOf,
        isKnown: isKnown,
        isValidated: isValidated,
        redRoundsOf: redRoundsOf,
        recordGreen: recordGreen,
        recordFailure: recordFailure,
        buildRegistryMarker: buildRegistryMarker,
        parseRegistryComments: parseRegistryComments,
        latestRegistry: latestRegistry
    };
}

/**
 * tcTriage.js — the gh-1329 mechanical triage engine for linked-TC failures
 * on bugs.
 *
 * Live pathology: any red linked TC was *defined* as "the fix did not work"
 * and bounced the bug to development (postStoryTestAutomationResults.js →
 * handleBugWithProductFailure). A red TC has four causes with different
 * owners — product regression, stale/misencoding test, environment shift,
 * flake — and only the first one belongs to the fix. Because the pipeline
 * could not attribute, one loop reproduced deterministically:
 * fix merged → sibling TC red → bug bounced → correct fix re-done → red again.
 *
 * The engine is the ticket's triage table, mechanical all the way:
 *
 *   Scoping    the bug's verdict is gated only by its OWN oracle TC
 *              (role "verifies: <BUG>"). Sibling/regression-guard failures
 *              route to test maintenance and never bounce the bug.
 *
 *   Fresh TCs  a TC that has never passed is unvalidated: its first run is
 *              validation, and a fresh TC cannot bounce the bug by
 *              construction — red first runs go to the TC-rework/review flow
 *              (does the TC encode the AC?).
 *
 *   Own oracle rework first, bounce only when the rework leg confirms the
 *              product genuinely violates the AC — bounded by the existing
 *              maxReworkRounds (escalation at the cap, no new counter).
 *
 *   Guards     mechanical, no agent judgment in the main path, in order:
 *                1. retry once on the same build (flake filter; green →
 *                   nothing happened);
 *                2. fingerprint lookup vs the last green run — same build
 *                   SHA: changed env → environment shift; both fingerprints
 *                   equal → flaky; a missing fingerprint half proves
 *                   nothing (evidence, never a default — the case falls
 *                   through to the differential rerun request),
 *                   both proven by lookup, zero further reruns;
 *                3. build changed → differential rerun on the lastGreenSha
 *                   build (scripted CI varies ONLY the build):
 *                   red there too → failure predates the change →
 *                   maintenance; green there → a commit in the range broke a
 *                   pinned behavior → EARNED bounce (bounded, escalation at
 *                   the cap); unavailable → request the rerun, bug parked.
 *
 *   Persistence nothing is dropped: every test-side verdict carries a
 *              ledgerEntry payload for the rolling TC-maintenance ledger
 *              (tcMaintenanceLedger.js); only ACTION_NONE (transient flake,
 *              green on retry) records nothing.
 *
 * Pure module — no dmtools globals, GraalJS-clean (var + plain functions,
 * JSON-safe data). Callers own all tracker/git side effects.
 */
'use strict';

// TC roles (gh-1329 §1). Absent metadata defaults to OWN — the legacy-safe
// reading: an unmarked TC keeps today's bounded bounce path instead of
// silently demoting every legacy TC to a non-gating guard.
var ROLE_OWN = 'own-oracle';
var ROLE_GUARD = 'regression-guard';
// A guard that verifies ANOTHER bug: its failures (even differential-green
// ones) belong to that bug's pipeline — within this run they route to
// maintenance and never bounce the bug being triaged.
var ROLE_SIBLING = 'sibling-guard';

var DEFAULT_MAX_REWORK_ROUNDS = 2;

// Verdict actions.
var ACTION_NONE = 'none';                        // retry green on the same build — nothing happened
var ACTION_REWORK = 'rework';                    // TC-rework leg owns it; bug unchanged
var ACTION_MAINTENANCE = 'maintenance';          // test-side finding; bug unchanged
var ACTION_DIFFERENTIAL = 'differential-rerun';  // scripted rerun on the last-green build; bug unchanged
var ACTION_BOUNCE = 'bounce';                    // earned bounce; bug → development
var ACTION_ESCALATE = 'escalate';                // bounce cap reached; owner escalation; bug unchanged

// ── role resolution ──────────────────────────────────────────────────────────

var GUARD_ROLE_WORDS = { 'regression guard': 1, 'regression-guard': 1, 'guard': 1, 'sibling': 1, 'prevention': 1 };
var OWN_ROLE_WORDS = { 'own': 1, 'own-oracle': 1, 'own oracle': 1, 'oracle': 1, 'verifies': 1, 'verification': 1, 'verifies-bug': 1 };

function normalizedWord(value) {
    return String(value || '').toLowerCase().trim();
}

function roleWordOf(entry) {
    var raw = entry && (entry.role !== undefined ? entry.role : entry.tcRole);
    return normalizedWord(typeof raw === 'string' ? raw : '');
}

function bugKeyEqual(a, b) {
    return normalizedWord(a) !== '' && normalizedWord(a) === normalizedWord(b);
}

/**
 * Resolves a TC's role from its metadata (result entry or linked-TC entry).
 * Order: explicit role word → verifies-key comparison → regressionGuard
 * boolean → default OWN. A guard whose verifies key names ANOTHER bug is a
 * SIBLING of this run.
 */
function explicitRoleWord(entry) {
    var word = roleWordOf(entry);
    if (GUARD_ROLE_WORDS[word]) return ROLE_GUARD;
    if (OWN_ROLE_WORDS[word]) return ROLE_OWN;
    return null;
}

function roleFromVerifies(entry, bugKey) {
    var verifies = typeof entry.verifies === 'string' ? entry.verifies : '';
    if (normalizedWord(verifies) === '') return null;
    if (!bugKeyEqual(verifies, bugKey)) return ROLE_SIBLING;
    return explicitRoleWord(entry) === ROLE_GUARD ? ROLE_GUARD : ROLE_OWN;
}

function resolveTcRole(entry, bugKey) {
    if (!entry) return ROLE_OWN;
    var byVerifies = roleFromVerifies(entry, bugKey);
    if (byVerifies) return byVerifies;
    var byWord = explicitRoleWord(entry);
    if (byWord) return byWord;
    if (entry.regressionGuard === true) return ROLE_GUARD;
    return ROLE_OWN;
}

// ── fingerprint helpers ──────────────────────────────────────────────────────

function present(value) {
    return value !== undefined && value !== null && String(value) !== '';
}

function positiveIntOr(value, fallback) {
    var n = parseInt(value, 10);
    return n > 0 ? n : fallback;
}

function nonNegativeIntOr(value, fallback) {
    var n = parseInt(value, 10);
    return isNaN(n) || n < 0 ? fallback : n;
}

/**
 * True when the current run ran the SAME build as the recorded last-green
 * run (fingerprint lookup — evidence, never a default).
 */
function sameBuild(current, lastGreen) {
    return !!(current && lastGreen &&
        present(current.sha) && present(lastGreen.sha) &&
        String(current.sha) === String(lastGreen.sha));
}

function envChanged(current, lastGreen) {
    return !!(current && lastGreen &&
        present(current.envFingerprint) && present(lastGreen.envFingerprint) &&
        String(current.envFingerprint) !== String(lastGreen.envFingerprint));
}

/**
 * A missing env fingerprint half on either side never proves sameness —
 * the comparison is evidence, not a default (gh-1329 review: an agent that
 * omitted envFingerprint must not have its red silently reclassified as
 * flaky).
 */
function fingerprintsUnproven(current, lastGreen) {
    return !(present(current.envFingerprint) && present(lastGreen.envFingerprint));
}

// ── verdict construction ─────────────────────────────────────────────────────

// Evidence carried onto every verdict: sha/env from the failing run and
// lastGreen* from the registry record are always present (null when
// absent); the optional input fields appear only when supplied.
var EVIDENCE_FIELD_TABLE = [
    { key: 'sha', source: 'current' },
    { key: 'envFingerprint', source: 'current' },
    { key: 'lastGreenSha', source: 'lastGreen', sourceKey: 'sha' },
    { key: 'lastGreenEnvFingerprint', source: 'lastGreen', sourceKey: 'envFingerprint' },
    { key: 'differential', optional: true },
    { key: 'acVerdict', optional: true },
    { key: 'errorClass', optional: true },
    { key: 'testPath', optional: true },
    { key: 'failedDescriptionFile', optional: true },
    { key: 'failureSummary', optional: true }
];

function evidenceSource(input, source) {
    return source ? (input[source] || {}) : input;
}

function pickEvidence(input) {
    var evidence = {};
    EVIDENCE_FIELD_TABLE.forEach(function(spec) {
        var src = evidenceSource(input, spec.source);
        var raw = src[spec.sourceKey || spec.key];
        if (present(raw)) {
            evidence[spec.key] = String(raw);
        } else if (!spec.optional) {
            evidence[spec.key] = null;
        }
    });
    if (input.retryGreen) evidence.retryGreen = true;
    return evidence;
}

function verdict(input, action, reason, withLedgerEntry) {
    var redRounds = nonNegativeIntOr(input.redRounds, 0);
    var v = {
        tcKey: String(input.tcKey || ''),
        role: (input.role === ROLE_GUARD || input.role === ROLE_SIBLING) ? input.role : ROLE_OWN,
        action: action,
        reason: reason,
        redRounds: redRounds,
        maxReworkRounds: positiveIntOr(input.maxReworkRounds, DEFAULT_MAX_REWORK_ROUNDS),
        evidence: pickEvidence(input)
    };
    if (withLedgerEntry !== false) {
        v.ledgerEntry = {
            id: null, // stamped by the ledger module (its identity scheme)
            tcKey: v.tcKey,
            role: v.role,
            verdict: action,
            reason: reason,
            evidence: v.evidence
        };
    }
    return v;
}

function bounceCapReached(input) {
    return nonNegativeIntOr(input.redRounds, 0) >= positiveIntOr(input.maxReworkRounds, DEFAULT_MAX_REWORK_ROUNDS);
}

// ── the mechanical table ─────────────────────────────────────────────────────

/**
 * Guard triage (§4) — validated guards only; no agent judgment. A SIBLING
 * (a guard verifying another bug) can never turn its mechanical outcomes
 * into THIS bug's bounce/escalation: those belong to the sibling's owner,
 * so they convert to owner-notified maintenance with the evidence intact.
 */
function triageValidatedGuard(input) {
    // 1. flake filter: a same-build retry that went green means nothing happened.
    if (input.retryGreen) {
        return verdict(input, ACTION_NONE, 'retry-green-on-same-build', false);
    }
    // 2.+3. fingerprint lookup vs the last green run, then the differential.
    if (sameBuild(input.current, input.lastGreen)) {
        return triageSameBuildGuard(input);
    }
    return triageBuildChangedGuard(input);
}

/**
 * Same-build red: a proven environment shift is maintenance; flaky requires
 * BOTH fingerprints (missing evidence never defaults to flaky — the
 * differential rerun must attribute it instead).
 */
function triageSameBuildGuard(input) {
    if (envChanged(input.current, input.lastGreen)) {
        return verdict(input, ACTION_MAINTENANCE, 'environment-shift');
    }
    if (fingerprintsUnproven(input.current, input.lastGreen)) {
        return verdict(input, ACTION_DIFFERENTIAL, 'rerun-requested-on-last-green-build');
    }
    return verdict(input, ACTION_MAINTENANCE, 'flaky-same-build');
}

/**
 * Build changed — the differential rerun attributes it (varies only the
 * build): red there too → failure predates the change → maintenance; green
 * there → EARNED bounce (bounded, escalation at the cap); unavailable →
 * request the rerun, bug parked.
 */
function triageBuildChangedGuard(input) {
    if (input.differential === 'red') {
        return verdict(input, ACTION_MAINTENANCE, 'failure-predates-change');
    }
    if (input.differential === 'green') {
        return triageDifferentialGreenGuard(input);
    }
    return verdict(input, ACTION_DIFFERENTIAL, 'rerun-requested-on-last-green-build');
}

function triageDifferentialGreenGuard(input) {
    if (input.role === ROLE_SIBLING) {
        return verdict(input, ACTION_MAINTENANCE, 'sibling-regression-owner-notified');
    }
    if (bounceCapReached(input)) {
        return verdict(input, ACTION_ESCALATE, 'bounce-cap-reached');
    }
    return verdict(input, ACTION_BOUNCE, 'regression-from-change-range');
}

/**
 * The scripted dispatcher's continuation (gh-1345): a parked differential
 * request has RUN on the last-green build — the outcome decides. Red there
 * → the failure predates the change → maintenance; green → the earned
 * bounce path (sibling-aware, escalation at the cap). This is the honest
 * mechanical continuation of a parked request: re-running triageFailure
 * with the parked evidence would loop (the same-build/unproven case
 * re-requests the differential instead of consuming the outcome).
 */
function triageDifferentialOutcome(input) {
    var resolved = input || {};
    if (resolved.differential === 'red') {
        return verdict(resolved, ACTION_MAINTENANCE, 'failure-predates-change');
    }
    return triageDifferentialGreenGuard(resolved);
}

/**
 * AC-gated path (§2 + §3) — fresh TCs and the bug's own oracle. Bounce only
 * when the rework leg confirms the product violates the AC; bounded.
 */
function triageAcGated(input) {
    if (input.acVerdict === 'violated') {
        if (bounceCapReached(input)) {
            return verdict(input, ACTION_ESCALATE, 'bounce-cap-reached');
        }
        return verdict(input, ACTION_BOUNCE, 'acceptance-criteria-violated');
    }
    if (input.acVerdict === 'intact') {
        return verdict(input, ACTION_MAINTENANCE, 'tc-misencodes-ac');
    }
    // No AC verdict yet — route to the rework/review leg. A fresh TC's first
    // run is validation; an exhausted rework budget sweeps the TC instead of
    // looping (and a fresh TC can never bounce by construction).
    if (!input.validated && bounceCapReached(input)) {
        return verdict(input, ACTION_MAINTENANCE, 'unfixable-in-rework');
    }
    if (!input.validated) {
        return verdict(input, ACTION_REWORK, 'fresh-tc-first-run-validation');
    }
    return verdict(input, ACTION_REWORK, 'own-oracle-ac-recheck');
}

/**
 * The whole triage for one failed TC run.
 *
 * input: {
 *   tcKey, role ('own-oracle' | 'regression-guard'), validated (has a
 *   last-green record), current: { sha, envFingerprint }, lastGreen:
 *   { sha, envFingerprint } | null, retryGreen (same-build retry passed),
 *   differential ('green'|'red'|'unavailable'|null — scripted rerun outcome
 *   on the lastGreenSha build), acVerdict ('violated'|'intact'|null — the
 *   rework leg's re-check), redRounds (consecutive red rounds for the TC),
 *   maxReworkRounds, errorClass, testPath, failedDescriptionFile,
 *   failureSummary
 * }
 */
function triageFailure(input) {
    var resolved = input || {};
    var role = resolved.role === ROLE_GUARD || resolved.role === ROLE_SIBLING ? resolved.role : ROLE_OWN;
    var normalized = Object.assign({}, resolved, { role: role });
    if (role !== ROLE_OWN && normalized.validated) {
        return triageValidatedGuard(normalized);
    }
    return triageAcGated(normalized);
}

// ── rendering (the async, owner-facing surface — never a blocking ask) ──────

function evidenceNote(v) {
    var parts = [];
    var e = v.evidence || {};
    if (e.lastGreenSha) parts.push('last green build ' + e.lastGreenSha);
    if (e.sha && e.sha !== e.lastGreenSha) parts.push('failing build ' + e.sha);
    if (e.differential) parts.push('differential rerun on the last-green build: ' + e.differential);
    if (e.errorClass) parts.push('error class: ' + e.errorClass);
    return parts.length ? ' (' + parts.join('; ') + ')' : '';
}

/**
 * The bounce comment: names the earned evidence per bounced TC (why this
 * bounce is attributed to the fix).
 */
function buildBounceComment(bouncedVerdicts) {
    var lines = ['The following Test Cases failed with a product regression:'];
    (bouncedVerdicts || []).forEach(function(v) {
        var summary = v.evidence && v.evidence.failureSummary ? ' — ' + v.evidence.failureSummary : '';
        lines.push('* ' + v.tcKey + summary + evidenceNote(v));
    });
    lines.push('');
    lines.push('Attribution (gh-1329): each listed TC passed on its last-green build and the same script ' +
        'fails on the current one — the Differential rerun isolated the change range, so this bounce is ' +
        'attributed to the fix, not to the test or the environment.');
    return lines.join('\n');
}

/**
 * The triage comment for test-side routes: informational digest of what was
 * routed where. The bug state is unchanged and nothing is asked of anyone.
 */
function buildTriageComment(routedVerdicts) {
    var lines = ['ℹ️ *Linked-TC failure triage (gh-1329)* — the bug state is unchanged; test-side findings were routed:'];
    (routedVerdicts || []).forEach(function(v) {
        lines.push('* ' + v.tcKey + ' — ' + v.reason.replace(/-/g, ' ') + ' → ' +
            (v.action === ACTION_DIFFERENTIAL ? 'differential rerun requested' : 'TC maintenance ledger') +
            evidenceNote(v));
    });
    lines.push('');
    lines.push('Findings are queued in the TC maintenance ledger and fixed in batched sweep PRs — no action is required right now.');
    return lines.join('\n');
}

/**
 * The owner escalation at the bounce cap: says what was observed, that the
 * loop stopped itself, and what a human needs to look at. Async by design.
 */
function buildEscalationComment(escalatedVerdicts) {
    var lines = ['🚨 *Bounce cap reached (gh-1329) — owner escalation*'];
    (escalatedVerdicts || []).forEach(function(v) {
        lines.push('* ' + v.tcKey + ' — repeated attributed failures (' + v.redRounds + '/' + v.maxReworkRounds +
            ' rounds)' + evidenceNote(v));
    });
    lines.push('');
    lines.push('The automated bounce loop stopped (no infinite re-fix laps). A human should arbitrate the ' +
        'change range vs the test expectation; the evidence lives in the TC maintenance ledger.');
    return lines.join('\n');
}

if (typeof module !== 'undefined' && module.exports) {
    module.exports = {
        ROLE_OWN: ROLE_OWN,
        ROLE_GUARD: ROLE_GUARD,
        ROLE_SIBLING: ROLE_SIBLING,
        DEFAULT_MAX_REWORK_ROUNDS: DEFAULT_MAX_REWORK_ROUNDS,
        ACTION_NONE: ACTION_NONE,
        ACTION_REWORK: ACTION_REWORK,
        ACTION_MAINTENANCE: ACTION_MAINTENANCE,
        ACTION_DIFFERENTIAL: ACTION_DIFFERENTIAL,
        ACTION_BOUNCE: ACTION_BOUNCE,
        ACTION_ESCALATE: ACTION_ESCALATE,
        resolveTcRole: resolveTcRole,
        triageFailure: triageFailure,
        triageDifferentialOutcome: triageDifferentialOutcome,
        buildBounceComment: buildBounceComment,
        buildTriageComment: buildTriageComment,
        buildEscalationComment: buildEscalationComment
    };
}

/**
 * tcMaintenanceLedger.js — the gh-1329 rolling TC-maintenance ledger (§5).
 *
 * "Nothing discarded": every test-side finding (stale guard, environment-
 * shifted TC, flaky, unfixable-in-rework, and the dev leg's structured
 * `test_suspected` claim) is appended — script, failed_description, error
 * class, SHA/fingerprint evidence — so automation findings are re-owned
 * instead of stranding bugs, and test debt is fixed in batched sweep PRs.
 *
 *   Identity    id = hash(tcKey + errorClass + script path). The same TC
 *               failing the same way refreshes its finding (occurrences++,
 *               latest evidence) instead of duplicating; a re-occurrence of
 *               a resolved finding REOPENS it (the sweep did not stick).
 *
 *   Lifecycle   open -> resolved (a sweep PR fixes the batch; resolvedVia
 *               names it) -> open again on re-occurrence. Append-only
 *               evidence is never rewritten; dispositions only flip status.
 *
 *   Storage     one machine-parseable marker comment per update on the bug
 *               ticket — the house `dmtools:` marker pattern (same family as
 *               the gh-1332 finding registry). The newest machine-authored
 *               marker wins; markers from any other identity are invisible.
 *               No configured machine identity → trust nothing.
 *
 *   Owner face  buildDigestComment renders the async digest (one section per
 *               open finding, explicit "no action required now" — humans
 *               meet a digest, never a blocking ask).
 *
 * Pure module — no dmtools globals; callers fetch comments and post the
 * built marker. GraalJS-clean (var + plain functions, JSON-safe data).
 */
'use strict';

var reviewVerdicts = require('./reviewVerdicts.js');

// The registry marker — one line, JSON payload, invisible in the rendered
// ticket (same protocol family as the gh-807 verdict / gh-1332 registry markers).
var MARKER_PREFIX = '<!-- dmtools:tc-maintenance-ledger ';
var MARKER_SUFFIX = ' -->';
var LEDGER_VERSION = 1;

var STATUS_OPEN = 'open';
var STATUS_RESOLVED = 'resolved';

var SOURCE_AUTOMATION = 'automation';
var SOURCE_DEV = 'dev';

// Marker-hygiene cap for free-text fields (agent-authored evidence can be
// arbitrarily large; the ledger carries pointers, not essays).
var MAX_NOTE_LENGTH = 500;

// ── identity ─────────────────────────────────────────────────────────────────

// FNV-1a (32-bit, Math.imul keeps the multiply exact) — same scheme as the
// gh-1332 finding registry; two bases concatenated → a 16-hex id. The hash
// helpers are the marker families' shared plumbing (reviewVerdicts —
// gh-1329 rework, gh-1251 duplication ratchet).

/**
 * The finding identity: hash(tcKey + errorClass + script path). NOT the SHA
 * (a re-run on a new build is the same finding) and NOT the verdict alone
 * (too coarse — one TC can flake AND misencode).
 */
function findingIdentity(tcKey, errorClass, testPath) {
    var key = String(tcKey || '') + '\n' + String(errorClass || 'unknown') + '\n' + String(testPath || '');
    return reviewVerdicts.hex8(reviewVerdicts.fnv1a(key, 0x811c9dc5)) + reviewVerdicts.hex8(reviewVerdicts.fnv1a(key, 0x811c9dc5 ^ 0x9e3779b9));
}

// ── shape ────────────────────────────────────────────────────────────────────

function emptyLedger() {
    return { v: LEDGER_VERSION, at: new Date().toISOString(), findings: [] };
}

function deepCopyLedger(l) {
    return JSON.parse(JSON.stringify(l || emptyLedger()));
}

function truncate(text) {
    var s = String(text || '');
    return s.length > MAX_NOTE_LENGTH ? s.substring(0, MAX_NOTE_LENGTH) : s;
}

function firstDefined(obj, keys) {
    for (var i = 0; i < keys.length; i++) {
        if (obj[keys[i]] !== undefined && obj[keys[i]] !== null && obj[keys[i]] !== '') return obj[keys[i]];
    }
    return null;
}

// Free-form finding fields copied from the source payload. `sources` lists
// the accepted spellings in priority order; `truncate` fields are
// marker-hygiene capped; `fallback` applies when every source is absent.
var FINDING_FIELD_TABLE = [
    { key: 'failedDescriptionFile', sources: ['failedDescriptionFile'] },
    { key: 'failureSummary', sources: ['failureSummary', 'summary'], truncate: true, fallback: '' },
    // An automation finding carries only an EXPLICIT note (gh-1329 review:
    // reason and note stay distinct — no truncated reason copy in every
    // marker); the dev claim builds its own additive note.
    { key: 'note', sources: ['note'], truncate: true },
    { key: 'claimedVerdict', sources: ['claimedVerdict'] },
    { key: 'evidence', sources: ['evidence'] },
    { key: 'sha', sources: ['sha', 'buildSha'] },
    { key: 'envFingerprint', sources: ['envFingerprint'] },
    { key: 'lastGreenSha', sources: ['lastGreenSha'] },
    { key: 'lastGreenEnvFingerprint', sources: ['lastGreenEnvFingerprint'] }
];

function findingField(src, spec) {
    var value = firstDefined(src, spec.sources);
    if (value === null) return spec.fallback !== undefined ? spec.fallback : null;
    return spec.truncate ? truncate(value) : value;
}

/** The identity-bearing core fields (they feed the finding id hash). */
function findingCoreFields(src) {
    return {
        tcKey: String(firstDefined(src, ['tcKey', 'testCaseKey']) || ''),
        errorClass: String(firstDefined(src, ['errorClass', 'error_class']) || 'unknown'),
        testPath: String(firstDefined(src, ['testPath', 'script']) || '')
    };
}

/**
 * Normalizes any finding input into the canonical ledger shape. Unknown
 * errorClass stays visible as 'unknown' — a finding is never silently
 * dropped for missing metadata.
 */
function normalizeFinding(input, at) {
    var src = input || {};
    var core = findingCoreFields(src);
    var finding = {
        id: findingIdentity(core.tcKey, core.errorClass, core.testPath),
        tcKey: core.tcKey,
        role: src.role || null,
        verdict: src.verdict || 'maintenance',
        reason: src.reason || null,
        errorClass: core.errorClass,
        testPath: core.testPath,
        source: src.source || SOURCE_AUTOMATION,
        status: STATUS_OPEN,
        firstSeenAt: at,
        lastSeenAt: at,
        occurrences: 1,
        resolvedAt: null,
        resolvedVia: null
    };
    FINDING_FIELD_TABLE.forEach(function(spec) {
        finding[spec.key] = findingField(src, spec);
    });
    return finding;
}

function findById(l, id) {
    for (var i = 0; i < l.findings.length; i++) {
        if (l.findings[i].id === id) return l.findings[i];
    }
    return null;
}

function refreshFinding(existing, incoming, at) {
    existing.lastSeenAt = at;
    existing.occurrences = (existing.occurrences || 1) + 1;
    // Latest evidence wins — the ledger documents the most recent lap.
    ['verdict', 'reason', 'sha', 'envFingerprint', 'lastGreenSha', 'lastGreenEnvFingerprint',
     'failedDescriptionFile', 'failureSummary', 'note', 'claimedVerdict', 'evidence'].forEach(function(k) {
        if (incoming[k] !== null && incoming[k] !== undefined) existing[k] = incoming[k];
    });
    if (existing.status === STATUS_RESOLVED) {
        // A resolved finding that broke again: the sweep did not stick — reopen.
        existing.status = STATUS_OPEN;
        existing.resolvedAt = null;
        existing.resolvedVia = null;
    }
    return existing;
}

/**
 * Appends a finding into a deep-copied ledger: identity match refreshes,
 * otherwise a new entry is pushed. Returns the new ledger (never mutates
 * the input).
 */
function appendFinding(prev, input) {
    var at = (input && input.at) || new Date().toISOString();
    var l = deepCopyLedger(prev);
    l.at = at;
    var incoming = normalizeFinding(input, at);
    var existing = findById(l, incoming.id);
    if (existing) {
        refreshFinding(existing, incoming, at);
    } else {
        l.findings.push(incoming);
    }
    return l;
}

/**
 * Marks the listed identities resolved (the sweep leg's disposition).
 * Unknown ids are ignored — the ledger is append-only evidence.
 */
function resolveFindings(prev, ids, via) {
    var at = new Date().toISOString();
    var l = deepCopyLedger(prev);
    l.at = at;
    (ids || []).forEach(function(id) {
        var f = findById(l, id);
        if (!f) return;
        f.status = STATUS_RESOLVED;
        f.resolvedAt = at;
        f.resolvedVia = via || null;
    });
    return l;
}

function openFindings(l) {
    if (!l || !Array.isArray(l.findings)) return [];
    return l.findings.filter(function(f) { return f.status === STATUS_OPEN; });
}

// The SM-routing label that anchors a parked differential request to the
// scripted dispatcher rule (gh-1345): the automation leg adds it when a run
// parks a request, the dispatcher clears it when nothing remains parked.
var PARK_LABEL = 'tc_differential_pending';

// The parked differential-rerun verdict (tcTriage ACTION_DIFFERENTIAL): the
// finding that awaits the scripted CI dispatcher — never a sweep item.
var VERDICT_DIFFERENTIAL = 'differential-rerun';

/**
 * The parked differential rerun requests of a ledger: open findings whose
 * verdict is the differential rerun — the TCs the dispatcher still has to run
 * on their last-green build. They stay parked (and visible in every digest)
 * until the dispatcher resolves them.
 */
function differentialRequests(l) {
    return openFindings(l).filter(function(f) { return f && f.verdict === VERDICT_DIFFERENTIAL; });
}

// ── finding builders (the two machine sources) ───────────────────────────────

var VERDICT_FALLBACK_TABLE = [
    { key: 'tcKey', entryKey: 'tcKey', verdictKey: 'tcKey' },
    { key: 'role', entryKey: 'role', verdictKey: 'role' },
    { key: 'verdict', entryKey: 'verdict', verdictKey: 'action' },
    { key: 'reason', entryKey: 'reason', verdictKey: 'reason' }
];

var VERDICT_EVIDENCE_FIELDS = ['errorClass', 'testPath', 'failedDescriptionFile', 'failureSummary',
    'sha', 'envFingerprint', 'lastGreenSha', 'lastGreenEnvFingerprint'];

function firstNonEmptyValue(a, b) {
    return (a !== undefined && a !== null && a !== '') ? a : b;
}

function verdictLedgerEntry(v) {
    return (v && v.ledgerEntry) || {};
}

function verdictEvidence(v, entry) {
    return entry.evidence || (v && v.evidence) || {};
}

/**
 * A triage verdict (tcTriage.js) becomes an automation-sourced finding.
 * Every verdict except ACTION_NONE carries a ledgerEntry payload — this
 * builder consumes it.
 */
function findingFromVerdict(v, opts) {
    var at = (opts && opts.at) || new Date().toISOString();
    var entry = verdictLedgerEntry(v);
    var evidence = verdictEvidence(v, entry);
    var verdictLike = v || {};
    var src = { source: SOURCE_AUTOMATION, at: at };
    VERDICT_FALLBACK_TABLE.forEach(function(spec) {
        src[spec.key] = firstNonEmptyValue(entry[spec.entryKey], verdictLike[spec.verdictKey]);
    });
    VERDICT_EVIDENCE_FIELDS.forEach(function(k) {
        src[k] = evidence[k];
    });
    return normalizeFinding(src, at);
}

/** The dev claim's additive note: reason + evidence pointer (never a bare reason copy). */
function devClaimNote(src) {
    var noteParts = [];
    if (src.reason) noteParts.push(String(src.reason));
    if (src.evidence) noteParts.push('evidence: ' + String(src.evidence));
    return noteParts.join(' — ');
}

function devClaimCoreFields(src) {
    return {
        tcKey: firstDefined(src, ['tcKey', 'testCaseKey']) || '',
        claimedVerdict: firstDefined(src, ['claimedVerdict', 'verdict']) || null,
        errorClass: firstDefined(src, ['errorClass']) || 'unknown',
        testPath: firstDefined(src, ['testPath', 'script']) || '',
        sha: firstDefined(src, ['sha', 'buildSha']) || null
    };
}

/**
 * The dev leg's structured exit (§6): outputs/test_suspected.json — the
 * claimed test-side verdict + evidence + TC key — machine-routed into the
 * ledger. Free text is truncated (marker hygiene) and the source is 'dev'.
 */
function findingFromDevClaim(claim, opts) {
    var src = claim || {};
    var core = devClaimCoreFields(src);
    core.verdict = 'dev-test-suspected';
    core.note = devClaimNote(src);
    core.source = SOURCE_DEV;
    return normalizeFinding(core, (opts && opts.at) || new Date().toISOString());
}

// ── marker persistence (the house dmtools: marker pattern) ───────────────────

// Marker hygiene (escaping) and the parse walk live in reviewVerdicts — the
// shared dmtools: marker plumbing (gh-1329 rework, gh-1251 duplication
// ratchet): this module keeps only its MARKER_PREFIX and payload adapter.

function ledgerPayload(l) {
    return {
        v: l.v || LEDGER_VERSION,
        at: l.at || new Date().toISOString(),
        findings: l.findings || []
    };
}

function openCount(l) {
    return openFindings(l).length;
}

function ledgerNote(l) {
    return '\uD83E\uDDFC TC maintenance ledger (gh-1329) — ' + openCount(l) +
        ' open test-side finding' + (openCount(l) === 1 ? '' : 's') +
        ', ' + (Array.isArray(l.findings) ? l.findings.length : 0) + ' total. Machine-managed sweep queue; please do not edit or reply.';
}

/**
 * Builds the ledger marker comment for an update: the machine-parseable
 * one-line payload plus a short human note. Returns null for a non-postable
 * ledger (no findings array — a ledger without findings is not a ledger).
 */
function buildLedgerMarker(l) {
    if (!l || !Array.isArray(l.findings)) return null;
    return MARKER_PREFIX + JSON.stringify(ledgerPayload(l), reviewVerdicts.markerSafeReplacer) + MARKER_SUFFIX + '\n' + ledgerNote(l);
}

function ledgerFromPayload(parsed) {
    if (!parsed || !Array.isArray(parsed.findings)) return null;
    return {
        v: parseInt(parsed.v, 10) || LEDGER_VERSION,
        at: String(parsed.at || ''),
        findings: parsed.findings
    };
}

/**
 * Parses ALL ledger records from a ticket comments payload — comments:
 * [{body}] (author fields consulted only when opts.authorLogins is passed).
 * FAILS CLOSED: no configured machine-identity allowlist trusts nothing
 * (the machineAuthor doctrine — stricter than the shape-agnostic shared
 * parser, because a maintenance ledger re-routes bug verdicts).
 * Returns records oldest-first.
 */
function parseLedgerComments(comments, opts) {
    return reviewVerdicts.parseMarkerComments(comments, opts, MARKER_PREFIX, MARKER_SUFFIX,
        function(parsed) {
            var l = ledgerFromPayload(parsed);
            return l ? { ledger: l, at: l.at } : null;
        }, true);
}

/**
 * The newest trusted ledger record for a ticket, or null when none exists.
 */
function latestLedger(comments, opts) {
    var records = parseLedgerComments(comments, opts);
    return records.length ? records[records.length - 1] : null;
}

// ── the owner-facing digest (§7: async, never a blocking ask) ────────────────

function findingLine(f) {
    var src = f.source === SOURCE_DEV ? 'dev claim' : f.verdict;
    return '- ' + f.tcKey + ' — ' + src + (f.reason ? ' (' + f.reason.replace(/-/g, ' ') + ')' : '') +
        (f.testPath ? ' — `' + f.testPath + '`' : '') +
        (f.occurrences > 1 ? ' — seen ' + f.occurrences + 'x' : '') +
        (f.source === SOURCE_DEV && f.claimedVerdict ? ' — claimed: ' + f.claimedVerdict : '');
}

/**
 * The parked differential request line (gh-1345): everything the scripted
 * dispatcher needs is on the line — TC, script, last-green build.
 */
function parkedRequestLine(f) {
    return '- ' + f.tcKey + (f.testPath ? ' — `' + f.testPath + '`' : '') +
        (f.lastGreenSha ? ' — last green build `' + f.lastGreenSha + '`' : '') +
        ' — waiting for the scripted differential rerun';
}

/**
 * The digest comment: the parked differential rerun requests ALWAYS get
 * their own section first (gh-1345 — attribution stalls are never silent:
 * a parked request is dispatcher work, not sweep work), then one section
 * per open sweep finding plus the explicit "no action required right now".
 */
function buildDigestComment(l) {
    var parked = differentialRequests(l);
    var open = openFindings(l).filter(function(f) { return !f || f.verdict !== VERDICT_DIFFERENTIAL; });
    if (!open.length && !parked.length) {
        return '\uD83E\uDDFC TC maintenance ledger (gh-1329) — no open findings. Test-side debt is clear.';
    }
    var lines = [];
    if (parked.length) {
        lines.push('\u23F3 Parked differential rerun requests (gh-1345) — ' + parked.length +
            ' attribution stall' + (parked.length === 1 ? '' : 's') + ', the scripted CI dispatcher owns these ' +
            '(each TC is rerun on its last-green build; the outcome bounces the bug or closes the request):');
        parked.forEach(function(f) {
            lines.push(parkedRequestLine(f));
        });
        lines.push('');
    }
    if (open.length) {
        lines.push('\uD83E\uDDFC TC maintenance ledger digest (gh-1329) — ' + open.length +
            ' open test-side finding' + (open.length === 1 ? '' : 's') + ', queued for a batched sweep PR:');
        open.forEach(function(f) {
            lines.push(findingLine(f));
        });
        lines.push('');
        lines.push('Findings are fixed in batched sweep PRs; tests re-enter validation afterwards. No action is required right now.');
    } else {
        lines.push('The dispatcher runs each parked TC on its last-green build on the next maintenance tick and resolves the request mechanically; no action is required right now.');
    }
    return lines.join('\n');
}

if (typeof module !== 'undefined' && module.exports) {
    module.exports = {
        MARKER_PREFIX: MARKER_PREFIX,
        MARKER_SUFFIX: MARKER_SUFFIX,
        LEDGER_VERSION: LEDGER_VERSION,
        STATUS_OPEN: STATUS_OPEN,
        STATUS_RESOLVED: STATUS_RESOLVED,
        SOURCE_AUTOMATION: SOURCE_AUTOMATION,
        SOURCE_DEV: SOURCE_DEV,
        findingIdentity: findingIdentity,
        emptyLedger: emptyLedger,
        appendFinding: appendFinding,
        resolveFindings: resolveFindings,
        openFindings: openFindings,
        findingFromVerdict: findingFromVerdict,
        findingFromDevClaim: findingFromDevClaim,
        buildLedgerMarker: buildLedgerMarker,
        parseLedgerComments: parseLedgerComments,
        latestLedger: latestLedger,
        buildDigestComment: buildDigestComment,
        VERDICT_DIFFERENTIAL: VERDICT_DIFFERENTIAL,
        PARK_LABEL: PARK_LABEL,
        differentialRequests: differentialRequests
    };
}

/**
 * Post Story Test Automation Results Action
 * 1. Reads outputs/story_test_automation_result.json
 * 2. Commits/pushes testing/ folder on test/{STORY_KEY} branch
 * 3. Creates PR to main
 * 4. Per linked Test Case:
 *    - status → In Review - Passed / In Review - Failed
 *    - failed TC: attach outputs/failed_description_{TC_KEY}.md and set Failed Reason field
 * 5. Moves Story → In Testing
 * 6. Triggers pr_story_test_automation_review
 *
 * gh-1008 CRAP split: tracker/git/marker/wiki helpers live in
 * js/postStoryTestAutomationShared.js; action() is a thin orchestrator.
 * gh-1080 CRAP split: the remaining action() phases (context build, result
 * validation, branch publish, finalization) are top-level step helpers —
 * tracker/git/file calls and their order are unchanged.
 */

var configLoader = require('./configLoader.js');
var prHelper = require('./common/pullRequest.js');
var autoStart = require('./common/autoStart.js');
const { GIT_CONFIG, LABELS, JIRA_FIELDS } = require('./config.js');
var outputFiles = require('./common/outputFiles.js');
var tokenUsageComment = require('./common/tokenUsageComment.js');
var shared = require('./postStoryTestAutomationShared.js');
// gh-1329: attribute linked-TC failures before bouncing a bug.
var tcTriage = require('./common/tcTriage.js');
var tcMaintenanceLedger = require('./common/tcMaintenanceLedger.js');
var tcRunRegistry = require('./common/tcRunRegistry.js');
// gh-1329 review: the shared "load bug bookkeeping" helper (one getIssue,
// one machine-author resolution) for both legs that read the markers.
var bugBookkeeping = require('./common/bugBookkeeping.js');

// Tracker-agnostic ticket operations (jira / ado / github) — created lazily per action() run.
var trackersModule = require('./common/trackers.js');
var trackerOps = shared.createTrackerHolder(trackersModule);
var initTracker = trackerOps.initTracker;
var getTracker = trackerOps.getTracker;

var gitOps = shared.createGitOps(prHelper);
var runInRepo = shared.runInRepo;
var outputReaders = shared.makeOutputFileReaders(outputFiles);
var readFile = outputReaders.readFile;
var readOutputFile = outputReaders.readOutputFile;

var RESUME_MARKER = 'outputs/.story-test-resume-attempted';

function cleanCommandOutput(output) {
    return prHelper.cleanCommandOutput(output);
}

function readResultJson(workingDir, storyKey) {
    try {
        const raw = readOutputFile('story_test_automation_result.json', workingDir, storyKey);
        if (!raw) {
            console.warn('outputs/story_test_automation_result.json is empty or missing');
            return null;
        }
        const rawString = String(raw);
        try {
            const parsed = JSON.parse(rawString);
            console.log('Story test result overall:', parsed.overall);
            return parsed;
        } catch (parseErr) {
            console.error('Failed to parse story_test_automation_result.json:', parseErr);
            console.error('Raw content preview (first 1000 chars):', rawString.substring(0, 1000));
            console.error('Raw content preview around error:', rawString.substring(Math.max(0, parseErr.pos - 100), parseErr.pos + 100));
            return null;
        }
    } catch (e) {
        console.error('Failed to read story_test_automation_result.json:', e);
        return null;
    }
}

function readLinkedTestCases(storyKey, testCaseType) {
    try {
        var raw = readFile('input/' + storyKey + '/linked_test_cases.json');
        if (raw) {
            var parsed = JSON.parse(raw);
            if (parsed && Array.isArray(parsed.testCases)) {
                console.log('Loaded', parsed.testCases.length, 'linked Test Case(s) from input folder');
                return parsed.testCases;
            }
        }
    } catch (e) {
        console.warn('Could not read linked_test_cases.json, falling back to JQL:', e);
    }

    try {
        var jql = 'issue in linkedIssues("' + storyKey + '") AND issuetype = "' + testCaseType + '"';
        // JQL text: provider-specific query (WIQL on ado)
        var results = getTracker().searchIssues(jql, { maxResults: 100, fields: ['key'] });
        return Array.isArray(results) ? results : [];
    } catch (e) {
        console.warn('Failed to fetch linked Test Cases from Jira:', e);
        return [];
    }
}

function getMissingTestCaseKeys(result, linkedTestCases) {
    var resultKeys = {};
    if (result && Array.isArray(result.results)) {
        result.results.forEach(function(r) {
            if (r.testCaseKey) resultKeys[r.testCaseKey] = true;
        });
    }
    return linkedTestCases
        .map(function(tc) { return tc.key; })
        .filter(function(key) { return key && !resultKeys[key]; });
}

function buildResumePrompt(storyKey, linkedTestCases, result, missingKeys) {
    var checkedKeys = [];
    if (result && Array.isArray(result.results)) {
        checkedKeys = result.results.map(function(r) { return r.testCaseKey; }).filter(Boolean);
    }

    var resultSchema = JSON.stringify({
        "$schema": "http://json-schema.org/draft-07/schema#",
        "type": "object",
        "required": ["storyKey", "overall", "summary", "results"],
        "properties": {
            "storyKey": { "type": "string", "const": storyKey },
            "overall": { "type": "string", "enum": ["passed", "failed", "in_progress"] },
            "summary": { "type": "string" },
            "results": {
                "type": "array",
                "items": {
                    "type": "object",
                    "required": ["testCaseKey", "status"],
                    "properties": {
                        "testCaseKey": { "type": "string", "pattern": "^TS-[0-9]+$" },
                        "status": { "type": "string", "enum": ["passed", "failed", "skipped", "irrelevant"] },
                        "testPath": { "type": "string" },
                        "failedDescriptionFile": { "type": "string" },
                        "failureSummary": { "type": "string" },
                        "errorClass": { "type": "string", "enum": ["element-not-found", "assertion", "timeout", "navigation", "crash", "unknown"] },
                        "envFingerprint": { "type": "string" },
                        "retryStatus": { "type": "string", "enum": ["green", "red"] },
                        "differential": { "type": "string", "enum": ["green", "red", "unavailable"] },
                        "acVerdict": { "type": "string", "enum": ["violated", "intact"] },
                        "role": { "type": "string" },
                        "verifies": { "type": "string" }
                    },
                    "additionalProperties": false
                }
            }
        },
        "additionalProperties": false
    }, null, 2);

    return 'RESUME TASK: The previous story test automation run did not verify all linked Test Cases.\n\n' +
        'Story: ' + storyKey + '\n' +
        'Linked Test Cases (' + linkedTestCases.length + '): ' + linkedTestCases.map(function(tc) { return tc.key; }).join(', ') + '\n' +
        'Already checked (' + checkedKeys.length + '): ' + (checkedKeys.join(', ') || 'none') + '\n' +
        'Still missing (' + missingKeys.length + '): ' + missingKeys.join(', ') + '\n\n' +
        'Instructions:\n' +
        '- Continue the same story test automation task in the same repository.\n' +
        '- For every missing Test Case, run/verify the corresponding automated test.\n' +
        '- Create or update outputs/story_test_automation_result.json with a top-level object that matches the JSON Schema below.\n' +
        '- Append a result entry for each missing Test Case:\n' +
        '  { "testCaseKey": "TS-XXX", "status": "passed" | "failed" | "skipped" | "irrelevant", "testPath": "testing/tests/TS-XXX/...", "failedDescriptionFile": "outputs/failed_description_TS-XXX.md", "failureSummary": "..." }\n' +
        '- If the result JSON file is missing, create it from scratch using the existing outputs/response.md and testing/tests/ files as evidence.\n' +
        '- If a test fails, write a failed description file and reference it in the result entry.\n' +
        '- Do NOT push changes; the post-action will commit and push after you finish.\n' +
        '- Do NOT move the Story to another status.\n' +
        '- Update outputs/response.md with a short summary of what was verified.\n' +
        '- Validate that outputs/story_test_automation_result.json is parseable JSON that conforms to the schema before stopping.\n\n' +
        'Required JSON schema for outputs/story_test_automation_result.json:\n' + resultSchema + '\n';
}

function attemptResumeIfOutputsIncomplete(storyKey, result, linkedTestCases, workingDir) {
    var missingKeys = getMissingTestCaseKeys(result, linkedTestCases);
    if (missingKeys.length === 0) {
        return { attempted: false, reason: 'complete' };
    }

    var attempt = shared.readAttemptMarker(RESUME_MARKER);
    var maxAttempts = 2;
    if (attempt >= maxAttempts) {
        console.warn('Story test resume attempts exhausted (' + attempt + '/' + maxAttempts + '). Missing TCs:', missingKeys.join(', '));
        return { attempted: false, reason: 'attempts-exhausted', missingKeys: missingKeys };
    }

    attempt += 1;
    shared.writeAttemptMarker(RESUME_MARKER, attempt);

    var prompt = buildResumePrompt(storyKey, linkedTestCases, result, missingKeys);

    var promptPath = 'outputs/.story-test-resume-prompt.md';
    try {
        file_write({ path: promptPath, content: prompt });
    } catch (e) {
        console.error('Failed to write story test resume prompt:', e);
        return { attempted: false, reason: 'write-failed', missingKeys: missingKeys };
    }

    // `--continue` alone resumes the most recent session in this directory; pairing it
    // with `--resume` is rejected by the Copilot CLI as mutually exclusive, which made
    // this recovery run fail deterministically before ever reaching the agent.
    var command = 'bash agents/scripts/run-agent.sh --continue ' + promptPath;
    console.log('Story test output incomplete — resuming agent for missing TCs (attempt ' + attempt + '/' + maxAttempts + '):', missingKeys.join(', '));
    try {
        var output = runInRepo(command, workingDir);
        console.log('Resume run output:', String(output || '').substring(0, 500));
    } catch (e) {
        console.warn('Story test resume run failed:', e);
    }

    return { attempted: true, attempt: attempt, missingKeys: missingKeys };
}

function readJiraComment(params, workingDir, storyKey) {
    var jiraComment = readOutputFile('tracker_comment.md', workingDir, storyKey);
    if (jiraComment) return jiraComment;

